<template><label class="ln-date-field"><span v-if="label">{{label}}</span><div><i>▣</i><input :value="modelValue" type="date" :disabled="disabled" @input="update"/><button v-if="clearable&&modelValue" type="button" aria-label="清除日期" @click="clear">×</button></div></label></template>
<script setup lang="ts">withDefaults(defineProps<{modelValue?:string;label?:string;clearable?:boolean;disabled?:boolean}>(),{modelValue:''});const emit=defineEmits<{(e:'update:modelValue',value:string):void;(e:'change',value:string):void}>();function setValue(value:string){emit('update:modelValue',value);emit('change',value)}function update(e:Event){setValue((e.target as HTMLInputElement).value)}function clear(){setValue('')}</script>
<style scoped lang="scss">.ln-date-field{display:grid;gap:6px;font-family:var(--ln-font);>span{font-size:12px;font-weight:540}>div{height:var(--ln-control-md);padding:0 8px;display:flex;align-items:center;gap:7px;border:1px solid var(--ln-border-strong);border-radius:var(--ln-radius-md);background:var(--ln-surface);&:focus-within{border-color:rgba(94,106,210,.62);box-shadow:0 0 0 2px var(--ln-accent-soft)}i{color:var(--ln-text-tertiary);font-size:10px;font-style:normal}input{min-width:0;flex:1;border:0;outline:0;background:transparent;color:var(--ln-text);font:12px var(--ln-font)}button{border:0;background:none;color:var(--ln-text-tertiary);cursor:pointer}}}</style>
